def process(precip_boston, precip_chatham, precip_amherst, precip_ashburnham):
    import pandas as pd

    def extract_total(df, region):
        # keep only actual year rows (numeric)
        d = df.copy()
        d['Year_num'] = pd.to_numeric(d['Year'], errors='coerce')
        d = d[d['Year_num'].notna()]
        d = d[d['Year_num'] == 2020]
        if d.empty:
            return pd.DataFrame([{'region': region, 'Jun': None, 'Jul': None, 'Aug': None, 'JJA_total': None}])
        row = d.iloc[0]
        def to_float(x):
            try:
                return float(x)
            except Exception:
                return None
        jun, jul, aug = map(to_float, [row.get('Jun'), row.get('Jul'), row.get('Aug')])
        total = None if any(v is None for v in [jun, jul, aug]) else (jun + jul + aug)
        return pd.DataFrame([{'region': region, 'Jun': jun, 'Jul': jul, 'Aug': aug, 'JJA_total': total}])

    out = pd.concat([
        extract_total(precip_boston, 'Boston'),
        extract_total(precip_chatham, 'Chatham'),
        extract_total(precip_amherst, 'Amherst'),
        extract_total(precip_ashburnham, 'Ashburnham'),
    ], ignore_index=True)
    return out
